/**
 * JavaScript for the explore button panel toggle.
 *
 * @module     local_customcatmenu/explore
 * @copyright  2025 Rashid <abdul.rashid@edzlms.com>
 * @license    https://edzlms.com/
 */
define(["jquery"],function($){return{init:function(){const e=$('li[data-key="exploremenu"]');if(e.length&&!$("#edz-explore-wrapper").length){const t=`<div class="edzmenu-hover-container" id="edz-explore-wrapper">${e.prop("outerHTML")}${window.exploreMenuHTML}</div>`;e.replaceWith(t)}$(document).on("mouseenter",".has-sub",function(){$(this).find(".submenu").stop(!0,!0).fadeIn(150)}).on("mouseleave",".has-sub",function(){$(this).find(".submenu").stop(!0,!0).fadeOut(150)})}}});
